import re, os, sys

root = "/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge"
pattern = re.compile(sys.argv[1])
declre = re.compile(r'^\s*(?:@\[[^\]]*\]\s*)?(?:private\s+|protected\s+|noncomputable\s+|scoped\s+|local\s+)*(theorem|lemma|def|instance|abbrev|class|structure|example|axiom)\b\s*(\S*)')

results = []
for dirpath, dirnames, filenames in os.walk(root):
    if '.lake' in dirpath: continue
    for fn in filenames:
        if not fn.endswith('.lean'): continue
        p = os.path.join(dirpath, fn)
        lines = open(p, encoding='utf-8').read().split('\n')
        # find comment ranges (block comments /- ... -/)
        incomment = [False]*len(lines)
        depth = 0
        for i, l in enumerate(lines):
            j = 0
            startdepth = depth
            while j < len(l):
                if l.startswith('/-', j):
                    depth += 1; j += 2
                elif l.startswith('-/', j):
                    depth = max(0, depth-1); j += 2
                elif l.startswith('--', j) and depth == 0:
                    break
                else:
                    j += 1
            incomment[i] = (startdepth > 0 or depth > 0)
        for i, l in enumerate(lines):
            if pattern.search(l) and not incomment[i]:
                # walk back to find decl
                name = None; dl = None
                for kk in range(i, -1, -1):
                    m = declre.match(lines[kk])
                    if m:
                        name = m.group(1) + ' ' + m.group(2); dl = kk+1; break
                    if lines[kk].strip().startswith('/--') or lines[kk].strip().startswith('/-!'):
                        break
                results.append((os.path.relpath(p, root), i+1, name, dl, l.strip()))
for r in results:
    print(f"{r[0]}:{r[1]}  decl={r[2]} @line {r[3]}")
print("TOTAL LINES:", len(results))
names = set((r[0], r[2], r[3]) for r in results)
print("DISTINCT DECLS:", len(names))
EOF
